/* tiny SVG charts */
function lineChart(vals, opts = {}) { const W = opts.w || 520, H = opts.h || 160, P = 26; if (!vals.length) return `<div class="lt-empty">No data yet. Add your first entry.</div>`; const mn = Math.min(...vals, opts.min ?? Infinity), mx = Math.max(...vals, opts.target ?? -Infinity); const span = mx - mn || 1; const X = (i) => P + (vals.length < 2 ? (W - 2 * P) / 2 : i / (vals.length - 1) * (W - 2 * P)); const Y = (v) => H - P - (v - mn) / span * (H - 2 * P);
  const d = vals.map((v, i) => (i ? 'L' : 'M') + X(i).toFixed(1) + ',' + Y(v).toFixed(1)).join(' '); const area = d + ` L${X(vals.length - 1)},${H - P} L${X(0)},${H - P} Z`;
  const tgt = opts.target !== undefined ? `<line x1="${P}" x2="${W - P}" y1="${Y(opts.target)}" y2="${Y(opts.target)}" stroke="#16a34a" stroke-dasharray="6 5" stroke-width="2"/><text x="${W - P}" y="${Y(opts.target) - 6}" text-anchor="end" font-size="12" fill="#16a34a">goal ${opts.target}</text>` : '';
  return `<svg class="lt-chart" style="--ar:${W / H}" viewBox="0 0 ${W} ${H}" role="img" aria-label="${opts.label || 'chart'}"><defs><linearGradient id="lg${opts.id || ''}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#38bdf8" stop-opacity=".45"/><stop offset="1" stop-color="#38bdf8" stop-opacity="0"/></linearGradient></defs><path d="${area}" fill="url(#lg${opts.id || ''})"/><path d="${d}" fill="none" stroke="#2563eb" stroke-width="3" stroke-linejoin="round"/>${vals.map((v, i) => `<circle cx="${X(i)}" cy="${Y(v)}" r="3.5" fill="#2563eb"/>`).join('')}${tgt}<text x="${P}" y="14" font-size="12" fill="#64748b">${mx}</text><text x="${P}" y="${H - 6}" font-size="12" fill="#64748b">${mn}</text></svg>`; }
function barChart(pairs, opts = {}) { const W = opts.w || 520, H = opts.h || 150, P = 22; const mx = Math.max(1, ...pairs.map(p => p[1])); const bw = (W - 2 * P) / pairs.length; return `<svg class="lt-chart" style="--ar:${W / H}" viewBox="0 0 ${W} ${H}" role="img" aria-label="${opts.label || 'bar chart'}">${pairs.map(([l, v], i) => { const h = v / mx * (H - 2 * P - 6); return `<rect x="${P + i * bw + bw * 0.18}" y="${H - P - h}" width="${bw * 0.64}" height="${h}" rx="6" fill="${opts.color || '#7c3aed'}"/><text x="${P + i * bw + bw / 2}" y="${H - 6}" font-size="11" text-anchor="middle" fill="#64748b">${l}</text>${v ? `<text x="${P + i * bw + bw / 2}" y="${H - P - h - 4}" font-size="11" text-anchor="middle" fill="#0f172a">${v}</text>` : ''}`; }).join('')}</svg>`; }

function heatmap(dayScore, weeks = 12) { const cell = 13, gap = 3; const W = weeks * (cell + gap) + 30, H = 7 * (cell + gap) + 20; const start = new Date(Date.now() - (weeks * 7 - 1) * 86400000); start.setDate(start.getDate() - start.getDay()); let out = ''; let mx = 1; const vals = []; for (let w = 0; w < weeks; w++) for (let d = 0; d < 7; d++) { const dt = new Date(start.getTime() + (w * 7 + d) * 86400000); const k = dt.toISOString().slice(0, 10); const v = dt > new Date() ? -1 : dayScore(k); vals.push([w, d, v, k]); if (v > mx) mx = v; }
  for (const [w, d, v, k] of vals) { const c = v < 0 ? '#f8fafc' : v === 0 ? '#e2e8f0' : `hsl(${150 - 20 * Math.min(1, v / mx)},${55 + 20 * (v / mx)}%,${70 - 38 * (v / mx)}%)`; out += `<rect x="${28 + w * (cell + gap)}" y="${d * (cell + gap)}" width="${cell}" height="${cell}" rx="3" fill="${c}"><title>${k}: ${Math.max(0, v)}</title></rect>`; }
  ['S', 'M', 'T', 'W', 'T', 'F', 'S'].forEach((l, i) => { if (i % 2) out += `<text x="0" y="${i * (cell + gap) + 11}" font-size="10" fill="#64748b">${l}</text>`; });
  return `<svg class="lt-chart" style="--ar:${W / H}" viewBox="0 0 ${W} ${H}" role="img" aria-label="activity heatmap">${out}</svg>`; }
function donut(parts, label) { const tot = parts.reduce((a, p) => a + p[1], 0) || 1; let a0 = -Math.PI / 2; const R = 60, r = 38, C = 70; const seg = parts.map(([n, v, col]) => { const a1 = a0 + v / tot * Math.PI * 2; const big = a1 - a0 > Math.PI ? 1 : 0; const p = (a, rr) => [C + Math.cos(a) * rr, C + Math.sin(a) * rr]; const [x0, y0] = p(a0, R), [x1, y1] = p(a1, R), [x2, y2] = p(a1, r), [x3, y3] = p(a0, r); const d = v ? `M${x0},${y0} A${R},${R} 0 ${big} 1 ${x1},${y1} L${x2},${y2} A${r},${r} 0 ${big} 0 ${x3},${y3} Z` : ''; a0 = a1; return `<path d="${d}" fill="${col}"><title>${n}: ${v}</title></path>`; }).join('');
  return `<div class="lt-donut"><svg viewBox="0 0 140 140" width="140" height="140" role="img" aria-label="${label}">${seg}<text x="70" y="76" text-anchor="middle" font-size="20" font-weight="800" fill="#1e1b4b">${parts.reduce((a, p) => a + p[1], 0)}</text></svg><div>${parts.map(([n, v, col]) => `<div><i style="background:${col}"></i>${n} <b>${v}</b></div>`).join('')}</div></div>`; }
function radar(wheel) { const keys = Object.keys(wheel); const n = keys.length, C = 110, R = 90; const pt = (i, v) => { const a = i / n * Math.PI * 2 - Math.PI / 2; return [C + Math.cos(a) * R * v / 10, C + Math.sin(a) * R * v / 10]; }; let grid = ''; for (const lv of [2.5, 5, 7.5, 10]) grid += `<polygon points="${keys.map((_, i) => pt(i, lv).join(',')).join(' ')}" fill="none" stroke="#e2e8f0"/>`; const poly = keys.map((k, i) => pt(i, wheel[k]).join(',')).join(' '); return `<svg class="lt-chart" style="--ar:1;max-height:240px" viewBox="0 0 220 220" role="img" aria-label="life balance radar">${grid}<polygon points="${poly}" fill="rgba(124,58,237,.28)" stroke="#7c3aed" stroke-width="2.5"/>${keys.map((k, i) => { const [x, y] = pt(i, 11.6); return `<text x="${x}" y="${y}" font-size="11" text-anchor="middle" fill="#334155">${k}</text>`; }).join('')}</svg>`; }
function icsFor(r) { const dt = new Date(r.at); const z = (d) => d.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, ''); const end = new Date(dt.getTime() + 15 * 60000); const rule = r.repeat === 'daily' ? 'RRULE:FREQ=DAILY\r\n' : r.repeat === 'weekly' ? 'RRULE:FREQ=WEEKLY\r\n' : '';
  return ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//allofus.one//LIFEboard//EN', 'BEGIN:VEVENT', 'UID:' + r.id + '@allofus.one', 'DTSTAMP:' + z(new Date()), 'DTSTART:' + z(dt), 'DTEND:' + z(end), 'SUMMARY:' + r.t.replace(/[,;]/g, ' '), 'DESCRIPTION:From your allofus.one LIFEboard', rule + 'BEGIN:VALARM', 'TRIGGER:-PT0M', 'ACTION:DISPLAY', 'DESCRIPTION:' + r.t.replace(/[,;]/g, ' '), 'END:VALARM', 'END:VEVENT', 'END:VCALENDAR'].join('\r\n'); }
function download(name, text, type = 'text/calendar') { const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([text], { type })); a.download = name; document.body.appendChild(a); a.click(); setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 500); }

