/* every renderer gets ctx = { main, lb, persist, header, show, me, app, toast, hug, halo, celebrate, notify, openWorlds, allTabs } */
function snakeInline(c, scoreEl) { const q = c.getContext('2d'); const W = 20, H = 15; let sn = [[10, 7], [9, 7], [8, 7]], d = [1, 0], nd = [1, 0], food = [15, 7], score = 0, alive = true, acc = 0, last = performance.now(); const place = () => { do { food = [Math.floor(Math.random() * W), Math.floor(Math.random() * H)]; } while (sn.some(s => s[0] === food[0] && s[1] === food[1])); }; const key = (e) => { if (!c.isConnected) { removeEventListener('keydown', key, true); return; } const m = { ArrowUp: [0, -1], w: [0, -1], ArrowDown: [0, 1], s: [0, 1], ArrowLeft: [-1, 0], a: [-1, 0], ArrowRight: [1, 0], d: [1, 0] }[e.key.length === 1 ? e.key.toLowerCase() : e.key]; if (!m) return; e.preventDefault(); e.stopPropagation(); if (m[0] !== -d[0] || m[1] !== -d[1]) nd = m; if (!alive) { sn = [[10, 7], [9, 7], [8, 7]]; d = [1, 0]; nd = [1, 0]; score = 0; alive = true; place(); } }; addEventListener('keydown', key, true); let sx = 0, sy = 0; c.onpointerdown = (e) => { sx = e.clientX; sy = e.clientY; if (!alive) { sn = [[10, 7], [9, 7], [8, 7]]; d = [1, 0]; nd = [1, 0]; score = 0; alive = true; place(); } }; c.onpointerup = (e) => { const dx = e.clientX - sx, dy = e.clientY - sy; if (Math.abs(dx) + Math.abs(dy) < 20) return; const m = Math.abs(dx) > Math.abs(dy) ? [Math.sign(dx), 0] : [0, Math.sign(dy)]; if (m[0] !== -d[0] || m[1] !== -d[1]) nd = m; };
  const loop = (now) => { if (!c.isConnected) return; const dt = (now - last) / 1000; last = now; acc += dt; if (alive && acc > Math.max(0.06, 0.13 - score * 0.003)) { acc = 0; d = nd; const h = [sn[0][0] + d[0], sn[0][1] + d[1]]; if (h[0] < 0 || h[1] < 0 || h[0] >= W || h[1] >= H || sn.some(s => s[0] === h[0] && s[1] === h[1])) alive = false; else { sn.unshift(h); if (h[0] === food[0] && h[1] === food[1]) { score++; place(); } else sn.pop(); } if (scoreEl) scoreEl.textContent = 'Score ' + score + (alive ? '' : ' · game over, tap or press a key'); } q.fillStyle = '#031208'; q.fillRect(0, 0, 400, 300); q.fillStyle = '#ff4f79'; q.fillRect(food[0] * 20 + 3, food[1] * 20 + 3, 14, 14); sn.forEach(([x, y], i) => { q.fillStyle = i ? '#3cff6e' : '#d1fae5'; q.fillRect(x * 20 + 1, y * 20 + 1, 18, 18); }); requestAnimationFrame(loop); }; requestAnimationFrame(loop); }
