      $('#st-add', main).onclick = () => { const q = $('#st-q', main).value.trim(), a = $('#st-a', main).value.trim(); if (!q || !a) return; S.cards.push({ q, a, box: 0, next: 0 }); persist(); show('study'); }; const cardEl = $('#st-card', main); if (cardEl) { let flipped = false; cardEl.onclick = (e) => { if (e.target.closest('[data-g]')) return; flipped = !flipped; $('#st-face', main).textContent = flipped ? due[0].a : due[0].q; $('#st-acts', main).style.display = flipped ? '' : 'none'; }; cardEl.querySelectorAll('[data-g]').forEach(b => b.onclick = () => { const g = +b.dataset.g; const c = due[0]; c.box = g === 2 ? Math.min(5, (c.box || 0) + 1) : g === 1 ? Math.max(0, (c.box || 0)) : 0; c.next = Date.now() + [1, 2, 4, 8, 16, 32][c.box] * 86400000 * (g === 0 ? 0.5 : 1); persist(); ctx.celebrate && g === 2 && ctx.celebrate('🎓'); show('study'); }); }
