      const streak = (() => { let s = 0; for (let i = 0; i < 365; i++) { const k = new Date(Date.now() - i * 86400000).toISOString().slice(0, 10); const any = lb.focus.some(f => f.d === k) || lb.journal.some(j => j.d === k) || lb.metrics.some(m => m.log.some(l => l.d === k)); if (any) s++; else if (i > 0) break; } return s; })();
