      $('#af-pin', main).onclick = () => { lb.aff.pinned = aff; persist(); ctx.halo && ctx.halo({ t: '✨ ' + aff, c: '#ffd23f', kind: 'affirmation' }); toast('😇 Pinned above your head for everyone to see.'); };
