      $$('[data-evi]', main).forEach(b => b.onclick = () => { const ev = lb.events.find(x => x.id === b.dataset.evi); download('allofus-event.ics', icsFor({ id: ev.id, t: ev.t + ' (allofus.one)', at: ev.at, repeat: 'none' })); });
