/* reminder checker: runs while the world is open */
export function startReminders(getLB, persist, notify, toast) { setInterval(() => { const lb = getLB(); if (!lb || !lb.reminders) return; const now = Date.now(); let changed = false; for (const r of lb.reminders) { if (r.done) continue; const at = new Date(r.at).getTime(); if (at <= now && !r.fired) { r.fired = true; changed = true; notify && notify('⏰ ' + r.t, 'From your LIFEboard'); toast && toast('⏰ Reminder: ' + r.t, 6000); if (r.repeat === 'daily' || r.repeat === 'weekly') { r.at = new Date(at + (r.repeat === 'daily' ? 86400000 : 7 * 86400000)).toISOString(); r.fired = false; } } } if (changed) persist(); }, 30000); }
function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }

